import re
for i in y:
    # Extract just the number from "BI-RADS-1", "BI-RADS-2", etc.
    # Find all digits in the string and convert to int
    match = re.search(r'\d+', i)
    if match:
        Y.append(int(match.group()))
    else:
        Y.append(0)  # Default value if no number found
